import json, urllib.parse, urllib.request, time, re, unicodedata
from concurrent.futures import ThreadPoolExecutor, as_completed

tracks=json.load(open("all_tracks_raw.json"))

def norm(s):
    s=unicodedata.normalize("NFKC", s or "")
    s=re.sub(r"[\u064B-\u065F\u0670\u0640]", "", s)  # Arabic diacritics/tatweel
    s=s.lower()
    s=re.sub(r"[^\w\u0600-\u06FF]+"," ",s)
    return " ".join(s.split())

def get(url):
    for attempt in range(3):
        try:
            req=urllib.request.Request(url, headers={"User-Agent":"lyrics-metadata-research/1.0"})
            with urllib.request.urlopen(req, timeout=30) as r:
                return json.load(r)
        except Exception as e:
            time.sleep(1+attempt)
    return []

def dur_sec(d):
    try:
        m,s=d.split(":"); return int(m)*60+int(s)
    except: return None

def search(t):
    title=t["title"]
    queries=[
        {"artist_name":"Fadel Chaker","track_name":title},
        {"q":f"Fadel Chaker {title}"},
    ]
    if t.get("titleRomanized"):
        queries.append({"artist_name":"Fadel Chaker","track_name":t["titleRomanized"]})
    seen={}
    for q in queries:
        for r in get("https://lrclib.net/api/search?"+urllib.parse.urlencode(q)):
            seen[r.get("id")]=r
        if seen: break
    tsec=dur_sec(t.get("duration",""))
    best=None; bestscore=-1
    nt=norm(title); ntr=norm(t.get("titleRomanized",""))
    for r in seen.values():
        if not r.get("plainLyrics"): continue
        rt=norm(r.get("trackName",""))
        score=0
        if rt==nt or (ntr and rt==ntr): score+=10
        elif nt and (nt in rt or rt in nt): score+=6
        elif ntr and (ntr in rt or rt in ntr): score+=5
        if tsec and r.get("duration"):
            diff=abs(tsec-r["duration"])
            if diff<=2: score+=5
            elif diff<=5: score+=3
            elif diff<=10: score+=1
            else: score-=3
        if score>bestscore:
            bestscore=score; best=r
    if best and bestscore>=6:
        return best
    return None

results={}
def work(t):
    return t["lfid"], search(t)

with ThreadPoolExecutor(max_workers=4) as ex:
    futs=[ex.submit(work,t) for t in tracks]
    for i,f in enumerate(as_completed(futs),1):
        lfid,r=f.result()
        results[lfid]=r
        if i%25==0: print(i,"done", flush=True)

matched=sum(1 for r in results.values() if r)
print("MATCHED",matched,"of",len(tracks))
json.dump(results, open("lrclib_matches.json","w"), ensure_ascii=False, indent=1)
